import { wordlist } from "../../deps/jsr.io/@scure/bip39/2.2.0/src/wordlists/english.js";
import { generateMnemonic as generateMnemonicBip39, mnemonicToSeedSync } from "../../deps/jsr.io/@scure/bip39/2.2.0/src/index.js";
import { HDKey } from "../../deps/jsr.io/@scure/bip32/2.2.0/index.js";
import isString, { isNonEmptyString } from "../utils/isString.js";
import isArray from "../utils/isArray.js";
const lengths = [12, 15, 18, 21, 24];
export const isMnemonicWord = (word) => {
    return isString(word) && wordlist.includes(word);
};
export const isMnemonic = (value) => {
    return isArray(value) && lengths.includes(value.length) && value.every(isMnemonicWord);
};
export const isMnemonicDisplay = (value) => {
    if (isString(value) === false)
        return false;
    try {
        fromMnemonicDisplay(value);
        return true;
    }
    catch {
        return false;
    }
};
export const displayMnemonic = (mnemonic) => {
    return mnemonic.join(" ");
};
export const fromMnemonicDisplay = (mnemonicString) => {
    const mnemonic = mnemonicString.split(" ");
    if (isMnemonic(mnemonic) === false)
        throw new Error("Invalid MnemonicDisplay");
    return mnemonic;
};
export const isMnemonicPassphrase = (value) => {
    return isNonEmptyString(value, true);
};
export const displayMnemonicDisplayWithPassphrase = (mnemonicDisplay, passphrase) => {
    return `${mnemonicDisplay}${passphrase ? ` ${passphrase}` : ""}`;
};
export const displayMnemonicWithPassphrase = (mnemonic, passphrase) => {
    return displayMnemonicDisplayWithPassphrase(displayMnemonic(mnemonic), passphrase);
};
export const fromMnemonicDisplayWithPassphrase = (mnemonicDisplayWithPassphrase) => {
    const parts = mnemonicDisplayWithPassphrase.split(" ");
    // Try to break off the largest possible valid mnemonic from the start
    for (const l of lengths.filter(l => l <= parts.length).reverse()) {
        const mnemonic = parts.slice(0, l);
        if (isMnemonic(mnemonic)) {
            const passphraseParts = parts.slice(l);
            const passphrase = passphraseParts.length > 0 ? passphraseParts.join(" ") : undefined;
            if (passphrase === undefined || isMnemonicPassphrase(passphrase)) {
                return [mnemonic, passphrase];
            }
        }
    }
    throw new Error("Invalid MnemonicDisplayWithPassphrase");
};
export const isMnemonicDisplayWithPassphrase = (value) => {
    if (isString(value) === false)
        return false;
    try {
        fromMnemonicDisplayWithPassphrase(value);
        return true;
    }
    catch {
        return false;
    }
};
export const generateMnemonic = (length = 12) => {
    const strength = (length / 3) * 32;
    const mnemonicString = generateMnemonicBip39(wordlist, strength);
    return mnemonicString.split(" ");
};
export const mnemonicToPrivateKey = (mnemonic, passphrase) => {
    const mnemonicString = displayMnemonic(mnemonic);
    const seed = mnemonicToSeedSync(mnemonicString, passphrase);
    const hdkey = HDKey.fromMasterSeed(seed);
    const privateKey = hdkey.privateKey;
    if (privateKey === null)
        throw new Error("Failed to derive private key");
    return privateKey;
};
